// Local banking model for UI acceptance testing. Replace with the bank API in production.
(()=>{
const PASSWORD_HASH='d684a7f74b1d440c7e2f4df18edad8e6e8957e395c915ba4f193b98112787b4d';
const makeAccount=(type,number,balance,status='Activa',spent=0)=>({type,number,balance,status,spent,spentDate:''});
const makeUser=(id,name,document,alias,accounts)=>({id,username:id,passwordHash:PASSWORD_HASH,profile:{name,document,email:id+'@example.com',phone:'+595 981 000 000',alias},accounts,transactions:[],settings:{notifications:true},cardFrozen:false});
function seed(){
const users=[makeUser('maria','María Teresa Bogado','4567890','maria.bogado',[makeAccount('Cuenta corriente','025748021',2500371),makeAccount('Caja de ahorro','025748022',350000)]),makeUser('lucia','Lucía Bogado','4567891','lucia.bogado',[makeAccount('Caja de ahorro','025748031',750000),makeAccount('Cuenta corriente','025748032',180000)]),makeUser('martin','Martín Benítez','4567892','martin.benitez',[makeAccount('Cuenta corriente','025748041',0)]),makeUser('ana','Ana López','4567893','ana.lopez',[makeAccount('Caja de ahorro','025748051',400000,'Bloqueada'),makeAccount('Cuenta corriente','025748052',0,'Cerrada')])];
users[0].transactions=[{id:'ESM-284103',title:'Lucía Bogado',amount:150000,category:'Transferencia recibida',date:'Hoy, 09:41',status:'Completada',account:0},{id:'ESM-284102',title:'Cantina Tecnología UNCA',amount:-5500,category:'Pago QR',kind:'qr',date:'Hoy, 08:20',status:'Completada',account:0},{id:'ESM-284101',title:'Martín Benítez',amount:-35000,category:'Almuerzo compartido',date:'Ayer, 13:12',status:'Completada',account:0},{id:'ESM-284100',title:'Supermercado Los Jardines',amount:-84200,category:'Pago QR',kind:'qr',date:'Ayer, 18:36',status:'Completada',account:0},{id:'ESM-284099',title:'Ahorro del mes',amount:350000,category:'Transferencia interna',date:'27 oct, 16:00',status:'Completada',account:1}];
return{version:2,users,external:[{bank:'Banco 2',number:'2001001',alias:'carlos.banco2',name:'Carlos Acosta',status:'Activa',balance:1000000},{bank:'Banco 3',number:'3001001',alias:'sofia.banco3',name:'Sofía Duarte',status:'Activa',balance:500000,pending:true},{bank:'Banco 4',number:'4001001',alias:'diego.banco4',name:'Diego Rojas',status:'Bloqueada',balance:250000},{bank:'SUDAMERIS',number:'025749001',alias:'cantina.unca',name:'Cantina Tecnología UNCA',status:'Activa',balance:0}],operations:{}};
}
function accountAlias(user,index){return user.profile.alias+(index?'.'+(index+1):'')}
function findDestination(db,bank,identifier){const key=String(identifier).trim().toLowerCase();if(bank==='SUDAMERIS'){for(const user of db.users){const i=user.accounts.findIndex((a,index)=>a.number===key||accountAlias(user,index).toLowerCase()===key);if(i>=0)return{user,index:i,account:user.accounts[i],name:user.profile.name}}}const item=db.external.find(a=>a.bank===bank&&(a.number===key||a.alias===key));return item?{account:item,name:item.name}:null}
function validateDestination(db,user,accountIndex,bank,identifier){const origin=user.accounts[accountIndex];if(origin.status!=='Activa')throw Error('Tu cuenta está '+origin.status.toLowerCase()+'. Elegí una cuenta activa.');const dest=findDestination(db,bank,identifier);if(!dest)throw Error('No encontramos esa cuenta o alias en el banco seleccionado.');if(dest.account===origin)throw Error('Elegí una cuenta de destino diferente de la cuenta de origen.');if(dest.account.status!=='Activa')throw Error('La cuenta de destino está '+dest.account.status.toLowerCase()+'.');return dest}
function execute(db,user,index,transfer,kind,id,now=new Date()){
if(db.operations[id])return db.operations[id];const origin=user.accounts[index];const dest=validateDestination(db,user,index,transfer.bank,transfer.destination);const amount=Number(transfer.amount);if(!Number.isSafeInteger(amount)||amount<1||amount>10000000)throw Error('Ingresá un importe entero entre 1 y 10.000.000 Gs.');const day=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Asuncion',year:'numeric',month:'2-digit',day:'2-digit'}).format(now);const spent=origin.spentDate===day?origin.spent:0;if(spent+amount>10000000)throw Error('Este envío supera el límite diario de 10.000.000 Gs.');if(amount>origin.balance)throw Error('Tu saldo disponible no alcanza para este envío.');
const pending=!!dest.account.pending;const date=now.toLocaleString('es-PY',{timeZone:'America/Asuncion',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});const transaction={id,title:dest.name,amount:-amount,category:transfer.concept||'Transferencia enviada',date,status:pending?'Pendiente':'Completada',account:index,kind};origin.balance-=amount;origin.spent=spent+amount;origin.spentDate=day;user.transactions.unshift(transaction);if(!pending){dest.account.balance+=amount;if(dest.user)dest.user.transactions.unshift({...transaction,title:user.profile.name,amount,category:transfer.concept||'Transferencia recibida',account:dest.index})}db.operations[id]=transaction;return transaction;
}
globalThis.EsmeraldaBank={seed,findDestination,validateDestination,execute,accountAlias};
})();
